/** Human quality evidence and approval are committed with the entire stock mutation. */
@Service public class QualityInventoryService {
 @Resource JdbcTemplate jdbc; @Resource StockCareService stockCare;
 private void need(boolean b,String m){if(!b)throw new IllegalArgumentException(m);}
 private Map<String,Object> one(String sql,Object... a){List<Map<String,Object>> r=jdbc.queryForList(sql,a);need(r.size()==1,"质量单或批次不存在或无权访问");return r.get(0);}
 public List<Map<String,Object>> batches(String c,String sku,String store){need(sku!=null&&!sku.trim().isEmpty()&&sku.length()<=128&&store.length()<=64,"请填写完整SKU，可选填写虚仓编码");return jdbc.queryForList("SELECT id,sku_sn,store_code,batch_code,zp_actual_number,cp_actual_number,zp_available_number,cp_available_number,zp_lock_number,cp_lock_number,version FROM wms_inventory_batch WHERE company_code=? AND sku_sn=?"+(store.isEmpty()?"":" AND store_code=?")+" ORDER BY id DESC LIMIT 100",store.isEmpty()?new Object[]{c,sku}:new Object[]{c,sku,store});}
 public Map<String,Object> detail(String c,long id){Map<String,Object> d=one("SELECT q.*,b.batch_code,b.zp_actual_number,b.cp_actual_number,b.zp_available_number,b.cp_available_number FROM oms_quality_order q JOIN wms_inventory_batch b ON b.company_code=q.company_code AND b.id=q.batch_id WHERE q.company_code=? AND q.id=?",c,id);if("FREEZE".equals(d.get("action"))&&"COMPLETED".equals(d.get("state")))d.put("stock",stockCare.report(c,s(d,"quality_sn")));return d;}
 public Map<String,Object> list(String c,Map<String,String> q){List<Object> a=new ArrayList<>(Collections.singletonList(c));String where=" WHERE q.company_code=?";for(String k:Arrays.asList("quality_sn","sku_sn","store_code","state")){String v=q.getOrDefault(k,"").trim();if(!v.isEmpty()){need(v.length()<=128,"筛选过长");where+=" AND q."+k+"=?";a.add(v);}}int page=Integer.parseInt(q.getOrDefault("pageNum","1")),size=Integer.parseInt(q.getOrDefault("pageSize","20"));need(page>=1&&page<=10000&&size>=1&&size<=100,"分页无效");long total=jdbc.queryForObject("SELECT COUNT(*) FROM oms_quality_order q"+where,Long.class,a.toArray());a.add(size);a.add((page-1)*size);return map("total",total,"rows",jdbc.queryForList("SELECT q.*,b.batch_code FROM oms_quality_order q JOIN wms_inventory_batch b ON b.company_code=q.company_code AND b.id=q.batch_id"+where+" ORDER BY q.id DESC LIMIT ? OFFSET ?",a.toArray()));}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
 public long create(String c,Map<String,Object> cmd,String actor){String request=s(cmd,"request_key"),action=s(cmd,"action"),type=s(cmd,"inventory_type"),reason=s(cmd,"reason"),evidence=s(cmd,"evidence");long qty=n(cmd,"quantity"),batch=n(cmd,"batch_id");need(request.matches("[A-Za-z0-9_-]{16,64}")&&Arrays.asList("FREEZE","UNFREEZE","CP_TO_ZP").contains(action)&&Arrays.asList("ZP","CP").contains(type)&&qty>0&&qty<=100000000&&reason.length()>=2&&reason.length()<=1000&&evidence.length()>=2&&evidence.length()<=1000,"请填写有效数量、处理方式、原因及依据");String digest=stockCare.hash(cmd);List<Map<String,Object>> old=jdbc.queryForList("SELECT id,request_hash FROM oms_quality_order WHERE company_code=? AND request_key=?",c,request);if(!old.isEmpty()){need(digest.equals(old.get(0).get("request_hash")),"重复创建内容发生变化");return n(old.get(0),"id");}Map<String,Object> b=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",c,batch);String source=s(cmd,"source_sn");if(action.equals("UNFREEZE")){Map<String,Object> origin=one("SELECT * FROM oms_quality_order WHERE company_code=? AND quality_sn=? AND action='FREEZE' AND state='COMPLETED'",c,source);need(n(origin,"batch_id")==batch&&type.equals(origin.get("inventory_type")),"解冻须使用原冻结单相同批次和正次品");}boolean confirmed=Boolean.TRUE.equals(cmd.get("warehouse_confirmed"));if(action.equals("CP_TO_ZP"))need(type.equals("CP")&&confirmed,"次品转正须确认仓库实际质检结果并填写凭证");String sn="ZJ"+UUID.randomUUID().toString().replace("-","");GeneratedKeyHolder key=new GeneratedKeyHolder();jdbc.update(conn->{java.sql.PreparedStatement p=conn.prepareStatement("INSERT INTO oms_quality_order(company_code,quality_sn,request_key,request_hash,action,batch_id,sku_sn,store_code,inventory_type,quantity,source_sn,reason,evidence,warehouse_confirmed,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",java.sql.Statement.RETURN_GENERATED_KEYS);Object[] a={c,sn,request,digest,action,batch,b.get("sku_sn"),b.get("store_code"),type,qty,source,reason,evidence,confirmed?1:0,actor};for(int i=0;i<a.length;i++)p.setObject(i+1,a[i]);return p;},key);return key.getKey().longValue();}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED,timeout=25)
 public Map<String,Object> review(String c,long id,Map<String,Object> cmd,String actor){Map<String,Object> hint=detail(c,id);one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=? FOR UPDATE",c,hint.get("sku_sn"));Map<String,Object> q=one("SELECT * FROM oms_quality_order WHERE company_code=? AND id=? FOR UPDATE",c,id);need(n(cmd,"control_version")==n(q,"control_version")&&"DRAFT".equals(q.get("state")),"质量单已经处理，请刷新核对");String decision=s(cmd,"decision"),reason=s(cmd,"reason");need(Arrays.asList("APPROVE","REJECT").contains(decision)&&reason.length()>=2&&reason.length()<=1000,"请填写审核结论与依据");if(decision.equals("APPROVE")){String action=s(q,"action"),sn=s(q,"quality_sn");long qty=n(q,"quantity");Map<String,Object> b=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",c,q.get("batch_id"));if(action.equals("FREEZE"))stockCare.execute(c,"reserve",map("document_sn",sn,"purpose","QUALITY","actor",actor,"lines",Collections.singletonList(map("line_key",id,"sku_sn",q.get("sku_sn"),"store_code",q.get("store_code"),"batch_code",b.get("batch_code"),"inventory_type",q.get("inventory_type"),"quantity",qty))));else if(action.equals("UNFREEZE"))stockCare.execute(c,"release",map("document_sn",q.get("source_sn"),"message_id",sn,"quantity",qty,"actor",actor));else{need(n(q,"warehouse_confirmed")==1,"缺少仓库质检确认");stockCare.convert(c,sn,n(q,"batch_id"),qty,actor);}}jdbc.update("UPDATE oms_quality_order SET state=?,reviewed_by=?,review_reason=?,control_version=control_version+1 WHERE company_code=? AND id=?",decision.equals("APPROVE")?"COMPLETED":"REJECTED",actor,reason,c,id);return detail(c,id);}
}
